-- Table: execution_maps
DROP TABLE IF EXISTS `execution_maps`;
CREATE TABLE `execution_maps` (
  `id` varchar(36) NOT NULL,
  `trialId` varchar(50) NOT NULL,
  `protocolId` int NOT NULL,
  `map_status` enum('draft','active','revised','archived') NOT NULL DEFAULT 'draft',
  `version` int NOT NULL DEFAULT '1',
  `metadata` json NOT NULL,
  `createdBy` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `launchedAt` timestamp NULL DEFAULT NULL,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_maps_trial` (`trialId`),
  KEY `idx_maps_status` (`map_status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

