-- Table: map_phases
DROP TABLE IF EXISTS `map_phases`;
CREATE TABLE `map_phases` (
  `id` varchar(36) NOT NULL,
  `mapId` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `phase_type` enum('screening','baseline','treatment_visit','follow_up','end_of_study','unscheduled','screen_fail','early_termination','custom') NOT NULL DEFAULT 'custom',
  `displayOrder` int NOT NULL,
  `color` varchar(7) NOT NULL DEFAULT '#3B82F6',
  `estimatedDate` timestamp NULL DEFAULT NULL,
  `windowStart` timestamp NULL DEFAULT NULL,
  `windowEnd` timestamp NULL DEFAULT NULL,
  `protocolRef` json DEFAULT NULL,
  `canvasX` float DEFAULT NULL,
  `canvasY` float DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
