  KEY `idx_map_dependencies_source` (`sourceTaskId`),
  KEY `idx_map_dependencies_target` (`targetTaskId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

