-- Table: map_task_status_history
DROP TABLE IF EXISTS `map_task_status_history`;
CREATE TABLE `map_task_status_history` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mapId` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `trialId` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `taskId` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `fromStatus` enum('suggested','confirmed','todo','in_progress','blocked','waiting','done','skipped','cancelled') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `toStatus` enum('suggested','confirmed','todo','in_progress','blocked','waiting','done','skipped','cancelled') COLLATE utf8mb4_unicode_ci NOT NULL,
  `reason` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'status_change',
  `changedBy` int DEFAULT NULL,
  `enteredAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `exitedAt` timestamp NULL DEFAULT NULL,
  `durationSeconds` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_task_status_history_map_task_entered` (`mapId`,`taskId`,`enteredAt`),
  KEY `idx_task_status_history_trial_entered` (`trialId`,`enteredAt`),
  KEY `idx_task_status_history_task_open` (`taskId`,`exitedAt`),
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

