-- Table: map_tasks
DROP TABLE IF EXISTS `map_tasks`;
CREATE TABLE `map_tasks` (
  `id` varchar(36) NOT NULL,
  `phaseId` varchar(36) NOT NULL,
  `mapId` varchar(36) NOT NULL,
  `name` varchar(500) NOT NULL,
  `description` text DEFAULT NULL,
  `task_category` enum('consent','eligibility','lab_sample','vital_signs','imaging','drug_administration','assessment','questionnaire','data_entry','coordination','documentation','follow_up','safety_reporting','regulatory','custom') NOT NULL DEFAULT 'custom',
  `task_priority` enum('critical','high','medium','low') NOT NULL DEFAULT 'medium',
  `task_status` enum('suggested','confirmed','todo','in_progress','blocked','waiting','done','skipped','cancelled') NOT NULL DEFAULT 'suggested',
  `blockedReason` text DEFAULT NULL,
  `blockedSince` timestamp NULL DEFAULT NULL,
  `task_role` enum('pi','sub_i','crc','nurse','pharmacist','lab_tech','data_manager','regulatory_coordinator','study_coordinator','custom') DEFAULT NULL,
  `assignedUserId` int DEFAULT NULL,
  `suggestedAssignee` varchar(255) DEFAULT NULL,
  `suggestedDate` timestamp NULL DEFAULT NULL,
  `dueDate` timestamp NULL DEFAULT NULL,
  `estimatedDuration` int DEFAULT NULL,
  `startDate` timestamp NULL DEFAULT NULL,
  `completedDate` timestamp NULL DEFAULT NULL,
  `orderInPhase` int NOT NULL DEFAULT '0',
  `canvasX` float DEFAULT NULL,
  `canvasY` float DEFAULT NULL,
  `map_task_created_by` enum('ai','user') NOT NULL DEFAULT 'ai',
  `aiConfidence` float DEFAULT NULL,
  `isCustom` tinyint(1) NOT NULL DEFAULT '0',
  `tags` json NOT NULL,
  `protocolRefs` json NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `conditionalNote` text DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_map_tasks_phase_order` (`phaseId`,`orderInPhase`),
  KEY `idx_map_tasks_dates` (`mapId`,`dueDate`,`suggestedDate`),
  KEY `idx_map_tasks_status` (`mapId`,`task_status`),
  KEY `idx_map_tasks_assignee` (`assignedUserId`,`task_status`),
  KEY `idx_map_tasks_map` (`mapId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

