-- Table: messages
DROP TABLE IF EXISTS `messages`;
CREATE TABLE `messages` (
  `id` varchar(36) NOT NULL,
  `conversationId` varchar(36) DEFAULT NULL,
  `threadId` varchar(36) DEFAULT NULL,
  `emailChainId` varchar(36) DEFAULT NULL,
  `senderId` int DEFAULT NULL,
  `collab_sender_type` enum('user','ai','system','email_external') NOT NULL DEFAULT 'user',
  `senderName` varchar(255) DEFAULT NULL,
  `senderEmail` varchar(320) DEFAULT NULL,
  `content` text NOT NULL,
  `collab_message_content_type` enum('text','protocol_snippet','task_card','ai_response','email') NOT NULL DEFAULT 'text',
  `embeddedContent` json DEFAULT NULL,
  `isAiGenerated` tinyint(1) NOT NULL DEFAULT '0',
  `aiModel` varchar(100) DEFAULT NULL,
  `aiLatencyMs` int DEFAULT NULL,
  `editedAt` timestamp NULL DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_collab_messages_conversation` (`conversationId`,`createdAt`),
  KEY `idx_collab_messages_thread` (`threadId`,`createdAt`),
  KEY `idx_collab_messages_email_chain` (`emailChainId`,`createdAt`),
  KEY `idx_collab_messages_sender` (`senderId`),
  KEY `idx_collab_messages_ai` (`isAiGenerated`,`createdAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

