-- Table: protocolSections
DROP TABLE IF EXISTS `protocolSections`;
CREATE TABLE `protocolSections` (
  `id` int NOT NULL AUTO_INCREMENT,
  `protocolId` int NOT NULL,
  `name` varchar(255) NOT NULL,
  `pageReference` varchar(50) DEFAULT NULL,
  `dateReference` varchar(50) DEFAULT NULL,
  `orderIndex` int NOT NULL,
  `parentSectionId` int DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1050001;

