-- Table: protocol_map_sections
DROP TABLE IF EXISTS `protocol_map_sections`;
CREATE TABLE `protocol_map_sections` (
  `id` varchar(36) NOT NULL,
  `protocolId` int NOT NULL,
  `mapId` varchar(36) NOT NULL,
  `name` varchar(255) NOT NULL,
  `protocol_map_section_type` enum('schedule','eligibility','procedure','safety','medication','randomization','lab','custom') NOT NULL DEFAULT 'custom',
  `pageStart` int DEFAULT NULL,
  `pageEnd` int DEFAULT NULL,
  `dateReference` timestamp NULL DEFAULT NULL,
  `parentSectionId` varchar(36) DEFAULT NULL,
  `linkedPhaseIds` json NOT NULL,
  `linkedTaskIds` json NOT NULL,
  `displayOrder` int NOT NULL DEFAULT '0',
  `isChecked` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_map_protocol_sections_map_order` (`mapId`,`displayOrder`),
  KEY `idx_map_protocol_sections_parent` (`parentSectionId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

