-- Table: protocols
DROP TABLE IF EXISTS `protocols`;
CREATE TABLE `protocols` (
  `id` int NOT NULL AUTO_INCREMENT,
  `trialId` varchar(50) NOT NULL,
  `filename` varchar(255) NOT NULL,
  `fileUrl` text NOT NULL,
  `fileKey` varchar(512) NOT NULL,
  `uploadedBy` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `fileSize` int NOT NULL,
  `category` varchar(100) NOT NULL,
  `documentVersion` varchar(50) DEFAULT NULL,
  `amendmentVersion` varchar(50) DEFAULT NULL,
  `releaseDate` varchar(50) DEFAULT NULL,
  `isCurrent` tinyint(1) NOT NULL DEFAULT '0',
  `archivedAt` timestamp NULL DEFAULT NULL,
  `sourceType` varchar(32) NOT NULL DEFAULT 'manual',
  `sourceReference` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1410001;

