-- Table: tasks
DROP TABLE IF EXISTS `tasks`;
CREATE TABLE `tasks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `phaseId` int NOT NULL,
  `name` varchar(500) NOT NULL,
  `suggestedAssigneeId` int DEFAULT NULL,
  `suggestedDate` timestamp NULL DEFAULT NULL,
  `duration` int DEFAULT NULL,
  `protocolSection` varchar(255) DEFAULT NULL,
  `protocolPage` int DEFAULT NULL,
  `status` enum('pending','completed','blocked') NOT NULL DEFAULT 'pending',
  `orderIndex` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=990001;

