-- Table: telemetry_events
DROP TABLE IF EXISTS `telemetry_events`;
CREATE TABLE `telemetry_events` (
  `id` varchar(36) NOT NULL,
  `eventType` varchar(100) NOT NULL,
  `timestamp` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `userId` varchar(64) DEFAULT NULL,
  `sessionId` varchar(128) NOT NULL,
  `entityType` varchar(64) DEFAULT NULL,
  `entityId` varchar(128) DEFAULT NULL,
  `action` varchar(64) NOT NULL,
  `payload` json DEFAULT NULL,
  `durationMs` int DEFAULT NULL,
  `aiInvolved` tinyint(1) NOT NULL DEFAULT '0',
  `aiOutput` text DEFAULT NULL,
  `aiSources` json DEFAULT NULL,
  `userCorrection` text DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

