-- Table: threads
DROP TABLE IF EXISTS `threads`;
CREATE TABLE `threads` (
  `id` varchar(36) NOT NULL,
  `trialId` varchar(50) NOT NULL,
  `title` varchar(500) NOT NULL,
  `collab_thread_category` enum('question','decision','issue','action_required','approval','clarification') NOT NULL,
  `collab_thread_status` enum('open','pending','resolved','closed') NOT NULL DEFAULT 'open',
  `resolvedBy` int DEFAULT NULL,
  `resolvedAt` timestamp NULL DEFAULT NULL,
  `resolutionSummary` text DEFAULT NULL,
  `aiContributed` tinyint(1) NOT NULL DEFAULT '0',
  `aiResolutionSuggested` tinyint(1) NOT NULL DEFAULT '0',
  `createdBy` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_collab_threads_trial` (`trialId`),
  KEY `idx_collab_threads_status` (`collab_thread_status`),
  KEY `idx_collab_threads_category` (`collab_thread_category`),
  KEY `idx_collab_threads_trial_status` (`trialId`,`collab_thread_status`),
  KEY `idx_collab_threads_updated` (`updatedAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

