-- Table: trials
DROP TABLE IF EXISTS `trials`;
CREATE TABLE `trials` (
  `id` varchar(50) NOT NULL,
  `title` varchar(500) NOT NULL,
  `protocolNumber` varchar(100) DEFAULT NULL,
  `description` text DEFAULT NULL,
  `phase` varchar(50) DEFAULT NULL,
  `status` enum('not-started','active','recruiting','on-hold','completed','terminated') NOT NULL DEFAULT 'not-started',
  `sponsor` varchar(255) DEFAULT NULL,
  `location` varchar(255) DEFAULT NULL,
  `startDate` timestamp NULL DEFAULT NULL,
  `endDate` timestamp NULL DEFAULT NULL,
  `principalInvestigator` varchar(255) DEFAULT NULL,
  `enrolledPatients` int DEFAULT '0',
  `targetPatients` int DEFAULT NULL,
  `completionPercentage` int DEFAULT '0',
  `createdBy` int NOT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `investigationalProduct` varchar(255) DEFAULT NULL,
  `indication` varchar(255) DEFAULT NULL,
  `nctNumber` varchar(50) DEFAULT NULL,
  `currentVersion` varchar(50) DEFAULT NULL,
  `amendmentVersion` varchar(50) DEFAULT NULL,
  `releaseDate` varchar(50) DEFAULT NULL,
  `sampleSize` varchar(50) DEFAULT NULL,
  `numberOfSites` varchar(50) DEFAULT NULL,
  `studyDuration` varchar(100) DEFAULT NULL,
  `studyDesignType` varchar(255) DEFAULT NULL,
  `primaryObjective` text DEFAULT NULL,
  `primaryEndpoint` text DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

